from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def extract_key_value_pairs(file_path: str, endpoint: str, api_key: str) -> dict:
    client = DocumentAnalysisClient(
        endpoint=endpoint, 
        credential=AzureKeyCredential(api_key)
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document("prebuilt-document", document=f)
        result = poller.result()

    extracted_data = {}
    for document in result.documents:
        for kv_pair in document.key_value_pairs:
            key_content = kv_pair.key.content.strip() if kv_pair.key else None
            value_content = kv_pair.value.content.strip() if kv_pair.value else None
            if key_content and value_content:
                extracted_data[key_content] = value_content

    return extracted_data
